        /** @description Estado atual da configuração do Keycloak (§ Configuração Dinâmica do Keycloak). `source` indica de onde vieram os valores exibidos: `database` (já foi salvo pelo menu Configurações > Keycloak — o que está em uso agora), `environment` (nunca foi salvo por esta tela; os valores vêm das variáveis de ambiente do processo) ou `unset` (nem banco nem ambiente têm um issuer configurado). Nunca inclui um client secret em texto plano — só se um está definido (`client_secret_set`). */
        KeycloakSettingsStatus: {
            /** @description Audiência (claim "aud") que todo access token precisa ter para ser aceito — normalmente igual ao client_id do backend. */
            audience: string;
            /** @description Client ID do client "confidential" do BACKEND no Keycloak — usado para checar o campo azp/resource_access de um token, nunca para autenticar o próprio backend contra o Keycloak. */
            client_id: string;
            /** @description Se um Client Secret do backend está salvo (nunca devolvido em texto plano). */
            client_secret_set: boolean;
            /** @description Client ID do client "public"/"confidential" usado pelo FRONTEND (NextAuth) para o login via navegador (Authorization Code + PKCE) — um client Keycloak diferente do client_id do backend. */
            frontend_client_id: string;
            /** @description Se um Client Secret do frontend está salvo (nunca devolvido em texto plano). */
            frontend_client_secret_set: boolean;
            /** @description URL do realm no Keycloak (ex. https://sso.orgao.gov.br/realms/nexus) — de onde o backend baixa o documento de discovery OIDC e as chaves públicas (JWKS) usadas para validar todo token recebido. */
            issuer_url: string;
            /** @description Nome do realm Keycloak — informativo (o backend descobre tudo que precisa a partir de issuer_url), mas exibido para conferência. */
            realm: string;
            /** @enum {string} */
            source: "database" | "environment" | "unset";
            /** Format: date-time */
            updated_at?: string;
            /** @description Subject (Keycloak) do administrador que salvou por último — presente só quando source=database. */
            updated_by?: string;
        };
        /** @description Resultado de um teste de conexão contra um issuer Keycloak — nunca persiste nada (§ Teste de Integração do Keycloak). */
        KeycloakTestResult: {
            /** @description Se client_id/client_secret foram informados e uma tentativa de token client_credentials foi feita. */
            credentials_checked: boolean;
            credentials_message: string;
            credentials_ok: boolean;
            discovery_message: string;
            /** @description Se o documento de discovery OIDC (`{issuer_url}/.well-known/openid-configuration`) respondeu com sucesso. */
            discovery_ok: boolean;
            /**
             * @description 'failed' bloqueia o salvamento (issuer inalcançável); 'warning' não bloqueia (ex.: credenciais não puderam ser confirmadas, o que é esperado para um client sem Service Accounts habilitado).
             * @enum {string}
             */
            status: "ok" | "warning" | "failed";
        };
